head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS90019.xml';
scwin.vMktactCd = '314'; //채권시장조치구분코드
scwin.pBndApplId = '';
scwin.vBndListProcsTpCd = 2; //채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.arrPar = new Array();
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vViewYN = 'Y';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.pBndApplId = scwin.arrPar[0].BND_APPL_ID;
    }
};



/********************************************** 
 * 함수명  	 : fn_dtl_sync
 * 설명       : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var dsNm = 'BNS_ISU_CHG_INFO';
    var qryId = '';
    var param = '';
    qryId = 'lds.stf.bnsisuchg.select.readIsuChgInfoMiscDelist';
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_BND_APPL_ID=' + scwin.pBndApplId;
    param += '&{P}V_VIEW_YN=' + scwin.vViewYN;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    scwin.arrPar[0] = {
        STD_CD: dts_DtlInfo.getCellData(1, "ISU_CD"),
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetParDelistRsn
 * 설명       : 상장페지 사유선택 (종목)  팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParDelistRsn = function(arrPar) {
    scwin.arrPar[0] = {
        BND_DELIST_CD: dts_DtlInfo.getCellData(1, "BND_DELIST_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParDelistRsn
 * 설명       : 상장페지 사유선택 (종목)  팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParDelistRsn = function(arrPar) {
    var getData = scwin.arrPar[0].BND_DELIST_CD + " " + scwin.arrPar[0].DELIST_RSN_DTL;
    $c.stf.setObjectValue(txb_DlstRsn2, getData);
    $c.stf.setObjectValue(txb_MemoContn2, scwin.arrPar[0].MEMO);

    /*
    if (getObjectValue(txb_MemoContn2) != '') {
    	//접수내역 관련근거
    	txb_MemoContn2.style.color = "#15549c";
    	txb_MemoContn2.style.backgroundColor = "#b9d4f7"			
    	txb_MemoContn2.readOnly = true;
    }else {
    	//접수내역 관련근거
    	txb_MemoContn2.style.color = "#343434";
    	txb_MemoContn2.style.backgroundColor = "#FFFFFF"			
    	txb_MemoContn2.readOnly = false;
    }
    */

};
scwin.gform_onload = function() {
    $c.stf.showObj(lbl_PopLoc, false); //팝업위치 레이블 숨김
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //패널라운드처리(접수)	
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo_Acpt); //패널라운드처리(상세)

    scwin.fn_SetParam(); //호출파라미터설정	
    scwin.fn_dtl_sync(); //상세조회

    /*
    //접수내역 관련근거
    txb_MemoContn2.style.color = "#15549c";
    txb_MemoContn2.style.backgroundColor = "#b9d4f7"			
    txb_MemoContn2.readOnly = true;
    */

};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    scwin.vDtlInfoRowCount = rowcount;
};
scwin.img_StrtDd2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    popUpCalendar2(edt_StrtDd2);
};
scwin.img_DlstRsn2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParDelistRsn;
    scwin.fn_SetPar = fn_SetParDelistRsn;
    $c.bns.fn_PopDelistRsnSearch(lbl_PopLoc);
};
scwin.btn_Dtl2_onclick = function() {
    if (scwin.vDtlInfoRowCount == 0) return;
    scwin.fn_GetPar = fn_GetParIsuDelInfo;
    $c.bns.fn_PopIsuDetail(lbl_PopLoc);
};
scwin.btn_Close2_onclick = async function() {
    await $c.frame.CloseFrame();
};
